import asyncio, os, sys
from playwright.async_api import async_playwright
H = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(H, "shots10")
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await (await b.new_context(viewport={"width":1440,"height":900})).new_page(); errs=[]
        pg.on("pageerror", lambda e: errs.append(str(e)[:300]))
        pg.on("console", lambda m: errs.append("console: " + m.text[:200]) if m.type == "error" else None)
        await pg.goto("file://" + H + "/t10.html"); await pg.wait_for_timeout(1200)
        await pg.evaluate("__tg.loadSample25()"); await pg.wait_for_timeout(300)
        print("lib:", await pg.evaluate("JSON.stringify([__tg.trkLib().length, __tg.STATE().truckPicsV, __tg.trkLib().filter(e=>e.vt).length])"))
        # migration from a 9.9 library
        print("migrate:", await pg.evaluate("""(()=>{ const S=__tg.STATE(); S.truckPics=[{id:'st-white',make:'Volvo',model:'VNL 760',years:'2018-2024',src:'starter:side_white',cut:1,top:'starter:top_white'},{id:'g-vnl2_670',make:'Volvo',model:'VNL 670',years:'2003-2017',src:'starter:g_vnl2_670',cut:1},{id:'g-vnl3_400',make:'Volvo',model:'VNL 400',years:'2018-2024',src:'data:image/png;base64,AA',cut:1},{id:'trk_mine',make:'Mack',model:'Anthem',years:'',src:'data:image/png;base64,AA',cut:1}]; S.truckPicsV=2;
          const L=__tg.trkLib(); return JSON.stringify([L.length, L.some(e=>e.id==='g-vnl2_670'), L.some(e=>e.id==='g-vnl3_400'), L.some(e=>e.id==='trk_mine'), S.truckPicsV]); })()"""))
        await pg.evaluate("__tg.loadSample25()"); await pg.wait_for_timeout(300)
        print("matches:", await pg.evaluate("""JSON.stringify([['2025','VNL 860'],['2016','VNL 670'],['2021','VNR 300'],['1999','VN'],['','VNR 660'],['2012','VNL 860'],['2024','Mack Anthem'],['2020','VHD 300'],['2026','VNR 660'],['2022','VNR Electric']].map(a=>{ const ro={year:a[0]?+a[0]:undefined, model:a[1]}; const m=__tg.trkMatch(ro); return a.join(' ')+' → '+m.st+' '+(m.entry?m.entry.id:'-'); }))"""))
        print("vin year:", await pg.evaluate("""JSON.stringify(['4V4NC9EH0GN104483','4V4NC9EH5SN104482'].map(v=>{ const t=__tg.truckYM({vin:v, model:'VNL 670'}); return v+' '+t.year+' '+t.yearFrom; }))"""))
        rid = await pg.evaluate("(()=>{ const r=__tg.STATE().ros.find(x=>!x.shop && x.model); const U=__tg.UI(); U.view='ros'; U.selectedRo=r.id; __tg.render(); return r.id; })()"); await pg.wait_for_timeout(1000)
        print("ro model:", await pg.evaluate(f"JSON.stringify([__tg.getRO('{rid}').model, __tg.getRO('{rid}').vin, __tg.truckYM(__tg.getRO('{rid}')).year, (__tg.trkModelFor(__tg.getRO('{rid}'))||{{}}).id])"))
        await pg.screenshot(path=os.path.join(OUT, "a_ro.png"), clip={"x":260,"y":40,"width":900,"height":300})
        await pg.evaluate("document.querySelector('.jc-host').shadowRoot.querySelector('.px-trk__cam').click()"); await pg.wait_for_timeout(500)
        print("dialog:", await pg.evaluate("!!document.getElementById('trk-dlg')"))
        await pg.screenshot(path=os.path.join(OUT, "a_dlg.png"))
        await pg.fill('[data-td-f=year]', '2016'); await pg.wait_for_timeout(150)
        await pg.fill('[data-td-f=model]', 'VNL 670'); await pg.wait_for_timeout(250)
        print("status:", await pg.evaluate("document.querySelector('.td-st').textContent"))
        await pg.click('[data-td=cat]'); await pg.wait_for_timeout(400)
        await pg.screenshot(path=os.path.join(OUT, "a_cat.png"))
        await pg.fill('[data-tc-q]', '2016'); await pg.wait_for_timeout(250)
        print("cat 2016:", await pg.evaluate("document.querySelectorAll('.tc-c').length"))
        await pg.click('.tc-c[data-id="vnl-03-670"]'); await pg.wait_for_timeout(200)
        await pg.screenshot(path=os.path.join(OUT, "a_cat2.png"))
        await pg.click('[data-tc=use]'); await pg.wait_for_timeout(300)
        print("after pick:", await pg.evaluate("document.querySelector('.td-st').textContent"), await pg.evaluate("document.querySelector('[data-td-f=body]').value"))
        await pg.click('[data-td=save]'); await pg.wait_for_timeout(200)
        await pg.screenshot(path=os.path.join(OUT, "a_saving.png"), clip={"x":300,"y":600,"width":840,"height":200})
        await pg.wait_for_timeout(1600)
        print("saved:", await pg.evaluate(f"JSON.stringify([!!document.getElementById('trk-dlg'), __tg.getRO('{rid}').year, __tg.getRO('{rid}').model, __tg.getRO('{rid}').trkBody])"))
        await pg.screenshot(path=os.path.join(OUT, "a_ro2.png"), clip={"x":260,"y":40,"width":900,"height":300})
        await pg.evaluate("__tg.undoLast()"); await pg.wait_for_timeout(500)
        print("undo:", await pg.evaluate(f"JSON.stringify([__tg.getRO('{rid}').year, __tg.getRO('{rid}').model, __tg.getRO('{rid}').trkBody])"))
        # search by year
        await pg.keyboard.press("Control+k"); await pg.wait_for_timeout(300); await pg.keyboard.type("vnl"); await pg.wait_for_timeout(300)
        print("search vnl:", await pg.evaluate("document.querySelectorAll('.pal-row').length"), await pg.evaluate("document.getElementById('pal-q').placeholder"))
        await pg.screenshot(path=os.path.join(OUT, "a_pal.png")); await pg.keyboard.press("Escape")
        await pg.evaluate("(()=>{ const U=__tg.UI(); U.view='foreman'; U.fmView='floor'; __tg.render(); })()"); await pg.wait_for_timeout(1200)
        await pg.screenshot(path=os.path.join(OUT, "a_fm.png"))
        print("bays:", await pg.evaluate("[document.querySelectorAll('.fm-ti.top.up').length, document.querySelectorAll('.fm-ti.top').length, document.querySelectorAll('.fm-ti').length]"))
        await pg.evaluate("(()=>{ const U=__tg.UI(); U.view='triage'; U.tgView='yard'; __tg.render(); })()"); await pg.wait_for_timeout(1200)
        await pg.screenshot(path=os.path.join(OUT, "a_yard.png"))
        print("yard tv:", await pg.evaluate("document.querySelectorAll('.tg-tv').length"))
        await pg.evaluate("(()=>{ const U=__tg.UI(); U.view='profile'; U.pxSec='data'; __tg.render(); })()"); await pg.wait_for_timeout(900)
        await pg.locator(".px-card:has([data-trk-card])").screenshot(path=os.path.join(OUT, "a_set.png"))
        print("errs", errs[:8]); await b.close()
asyncio.run(main())
